import unreal,json
rows=[]
for n in ['SM_MallBalconyStraight_400','SM_MallBalconyModule_400']:
 m=unreal.load_asset('/Game/Environment/Mall/Models/Architecture/'+n); b=m.get_editor_property('BodySetup'); rows.append({'mesh':n,'body':b.get_path_name() if b else None,'trace':str(b.get_editor_property('CollisionTraceFlag')) if b else None,'double_sided':b.get_editor_property('bDoubleSidedGeometry') if b else None})
actors=unreal.get_editor_subsystem(unreal.EditorActorSubsystem).get_all_level_actors(); examples=[]
for a in actors:
 if a.get_actor_label() in ['Gallery_F1_Platform_01','Gallery_F1_Platform_02','Gallery_F1_Platform_03','Gallery_F1_Floor_01']:
  c=a.get_component_by_class(unreal.StaticMeshComponent); examples.append({'label':a.get_actor_label(),'location':str(a.get_actor_location()),'rotation':str(a.get_actor_rotation()),'collision':str(c.get_collision_enabled()) if c else None,'profile':str(c.get_collision_profile_name()) if c else None,'mesh':c.get_editor_property('StaticMesh').get_path_name() if c and c.get_editor_property('StaticMesh') else None})
unreal.log(json.dumps({'bodies':rows,'components':examples}))
